function resizeCanvas(canvas){
  const w = canvas.parentElement.clientWidth-60;
  canvas.style.width=w+'px'; canvas.width=w*devicePixelRatio;
  canvas.height=(w*0.5)*devicePixelRatio; canvas.style.height=(w*0.5)+'px';
}

