// ── SCATTER ───────────────────────────────────────────────────────────────────
const sc = document.getElementById('scatterCanvas');
const sCtx = sc.getContext('2d');
let scatterFilter='all', lyricFilter='all', hoveredPt=null;

const tempoColors = {slow:'#60a5fa', mid:'#f5c842', fast:'#e8345a'};

function drawScatter(){
  resizeCanvas(sc);
  const W=sc.width,H=sc.height,dpr=devicePixelRatio;
  const pad={left:52*dpr,right:20*dpr,top:20*dpr,bottom:44*dpr};
  const pw=W-pad.left-pad.right, ph=H-pad.top-pad.bottom;
  const ctx=sCtx;
  ctx.clearRect(0,0,W,H);

  // Grid
  ctx.strokeStyle='rgba(42,42,53,0.9)'; ctx.lineWidth=1;
  for(let i=0;i<=10;i++){
    ctx.beginPath();ctx.moveTo(pad.left+(i/10)*pw,pad.top);ctx.lineTo(pad.left+(i/10)*pw,pad.top+ph);ctx.stroke();
    ctx.beginPath();ctx.moveTo(pad.left,pad.top+(i/10)*ph);ctx.lineTo(pad.left+pw,pad.top+(i/10)*ph);ctx.stroke();
  }
  // Axis tick labels
  ctx.fillStyle='rgba(153,153,170,0.8)'; ctx.font=`${9*dpr}px DM Mono,monospace`;
  ctx.textAlign='center';
  for(let i=0;i<=10;i+=2) ctx.fillText((i/10).toFixed(1),pad.left+(i/10)*pw,H-6*dpr);
  ctx.textAlign='right';
  for(let i=0;i<=10;i+=2) ctx.fillText((i/10).toFixed(1),pad.left-6*dpr,pad.top+ph-(i/10)*ph+4*dpr);
  // Axis titles
  ctx.fillStyle='rgba(153,153,170,0.9)'; ctx.font=`${10*dpr}px DM Mono,monospace`;
  ctx.textAlign='center'; ctx.fillText('Valence',pad.left+pw/2,H);
  ctx.save(); ctx.translate(12*dpr,pad.top+ph/2); ctx.rotate(-Math.PI/2);
  ctx.fillText('Energy',0,0); ctx.restore();

  // Points
  scatterData.forEach((d,idx)=>{
    const tp = scatterFilter==='all'||d.t===scatterFilter;
    const lp = lyricFilter==='all'||(lyricFilter==='explicit'?d.x:!d.x);
    const ap = selectedArtists.size===0||selectedArtists.has(d.a);
    if(!tp||!lp||!ap) return;
    const x=pad.left+d.v*pw, y=pad.top+ph-d.e*ph;
    const c=tempoColors[d.t];
    const ra=parseInt(c.slice(1,3),16),ga=parseInt(c.slice(3,5),16),ba=parseInt(c.slice(5,7),16);
    const alpha=hoveredPt!=null?(hoveredPt===idx?1:0.12):0.68;
    const r=(d.x?4.5:3.2)*dpr;
    ctx.beginPath();
    if(d.x){ctx.moveTo(x,y-r*1.3);ctx.lineTo(x+r*1.3,y);ctx.lineTo(x,y+r*1.3);ctx.lineTo(x-r*1.3,y);ctx.closePath();}
    else ctx.arc(x,y,r,0,Math.PI*2);
    ctx.fillStyle=`rgba(${ra},${ga},${ba},${alpha})`;
    ctx.strokeStyle=hoveredPt===idx?'#fff':'transparent'; ctx.lineWidth=1.5;
    ctx.fill(); ctx.stroke();
  });

  // Legend
  const lgx=pad.left+pw-200*dpr, lgy=pad.top+16*dpr;
  [['slow','<100 BPM','#60a5fa'],['mid','100-145 BPM','#f5c842'],['fast','>145 BPM','#e8345a']].forEach(([k,lab,c],i)=>{
    const lx=lgx, ly=lgy+i*18*dpr;
    ctx.beginPath(); ctx.arc(lx,ly,4*dpr,0,Math.PI*2);
    ctx.fillStyle=c; ctx.fill();
    ctx.fillStyle='rgba(200,200,215,0.85)'; ctx.font=`${9*dpr}px DM Mono,monospace`; ctx.textAlign='left';
    ctx.fillText(lab,lx+10*dpr,ly+3*dpr);
  });
  // Explicit marker legend
  const ex=lgx, ey=lgy+3*18*dpr+6*dpr;
  ctx.beginPath(); ctx.moveTo(ex,ey-5*dpr);ctx.lineTo(ex+5*dpr,ey);ctx.lineTo(ex,ey+5*dpr);ctx.lineTo(ex-5*dpr,ey);ctx.closePath();
  ctx.fillStyle='rgba(200,200,215,0.6)'; ctx.fill();
  ctx.fillStyle='rgba(200,200,215,0.85)'; ctx.font=`${9*dpr}px DM Mono,monospace`; ctx.textAlign='left';
  ctx.fillText('◆ = Explicit',ex+10*dpr,ey+3*dpr);
}

sc.addEventListener('mousemove',e=>{
  const rect=sc.getBoundingClientRect(), dpr=devicePixelRatio;
  const W=sc.width,H=sc.height;
  const pad={left:52*dpr,right:20*dpr,top:20*dpr,bottom:44*dpr};
  const pw=W-pad.left-pad.right,ph=H-pad.top-pad.bottom;
  const mx=(e.clientX-rect.left)*dpr,my=(e.clientY-rect.top)*dpr;
  let found=null;
  scatterData.forEach((d,idx)=>{
    const tp=scatterFilter==='all'||d.t===scatterFilter;
    const lp=lyricFilter==='all'||(lyricFilter==='explicit'?d.x:!d.x);
    const ap2=selectedArtists.size===0||selectedArtists.has(d.a);
    if(!tp||!lp||!ap2) return;
    const x=pad.left+d.v*pw,y=pad.top+ph-d.e*ph;
    if(Math.sqrt((mx-x)**2+(my-y)**2)<10*dpr) found=idx;
  });
  hoveredPt=found;
  if(found!=null){const d=scatterData[found];showTip(`<b>${d.n}</b><br><span style='color:var(--text-dim)'>${d.a}</span><br>Energy: ${d.e} · Valence: ${d.v}<br>Tempo: ${d.t} · ${d.x?'🔞 Explicit':'✓ Clean'}`,e.clientX,e.clientY);}
  else hideTip();
  drawScatter();
});
sc.addEventListener('mouseleave',()=>{hoveredPt=null;hideTip();drawScatter();});

