// ── SANKEY ────────────────────────────────────────────────────────────────────
const sk=document.getElementById('sankeyCanvas');
const kCtx=sk.getContext('2d');
let sankeyNmap={}, sankeyNodeW=16, sankeyDpr=1;
let sankeyFlowCache=[]; // stores geometry + metadata for each flow for hit-testing
let hoveredFlow=null;

function buildFlowPath(ctx, x0,y0,x1,y1,fh){
  const cx=(x0+x1)/2;
  const p=new Path2D();
  p.moveTo(x0,y0);p.bezierCurveTo(cx,y0,cx,y1,x1,y1);
  p.lineTo(x1,y1+fh);p.bezierCurveTo(cx,y1+fh,cx,y0+fh,x0,y0+fh);
  p.closePath();
  return p;
}

function drawSankey(){
  resizeCanvas(sk);
  const W=sk.width,H=sk.height,dpr=devicePixelRatio;
  sankeyDpr=dpr;
  const pad={left:80*dpr,right:90*dpr,top:56*dpr,bottom:20*dpr};
  const pw=W-pad.left-pad.right,ph=H-pad.top-pad.bottom;
  const total=1000, nodeW=16*dpr;
  sankeyNodeW=nodeW;
  const colX=sankeyData.cols.map((_,i)=>pad.left+(i/(sankeyData.cols.length-1))*pw);
  const ctx=kCtx;
  ctx.clearRect(0,0,W,H);

  // Pre-compute node positions
  const nmap={};
  sankeyData.cols.forEach((col,ci)=>{
    const x=colX[ci];
    const totalH=col.nodes.reduce((s,n)=>s+(n.value/total)*ph,0);
    const spacing=(ph-totalH)/(col.nodes.length+1);
    let y=pad.top+spacing;
    ctx.fillStyle='rgba(153,153,170,0.7)';ctx.font=`${9*dpr}px DM Mono,monospace`;ctx.textAlign='center';
    ctx.fillText(col.label,x,pad.top-22*dpr);
    col.nodes.forEach(n=>{
      const h=(n.value/total)*ph;
      nmap[n.id]={x,y,h,color:n.color,node:n,ci,colLabel:col.label};
      y+=h+spacing;
    });
  });
  sankeyNmap=nmap;

  // Offsets for flow stacking
  const fromOff={},toOff={};
  Object.keys(nmap).forEach(k=>{fromOff[k]=0;toOff[k]=0;});

  // Build + draw flows, cache geometry for hit-testing
  sankeyFlowCache=[];
  sankeyData.flows.forEach(f=>{
    const src=nmap[f.from],dst=nmap[f.to];
    if(!src||!dst) return;
    const fh=(f.v/total)*ph;
    const x0=src.x+nodeW,y0=src.y+fromOff[f.from];
    const x1=dst.x,y1=dst.y+toOff[f.to];
    fromOff[f.from]+=fh; toOff[f.to]+=fh;
    const cx=(x0+x1)/2;
    // midpoint on the bezier at t=0.5
    const mx_mid=0.125*x0+0.375*cx+0.375*cx+0.125*x1;
    const my_top=0.125*y0+0.375*y0+0.375*y1+0.125*y1;   // top curve mid
    const my_bot=0.125*(y0+fh)+0.375*(y0+fh)+0.375*(y1+fh)+0.125*(y1+fh);
    const midY=(my_top+my_bot)/2;

    const path=buildFlowPath(ctx,x0,y0,x1,y1,fh);
    sankeyFlowCache.push({
      path, flow:f, src, dst, fh,
      x0,y0,x1,y1,cx,
      midX:mx_mid, midY,
      labelX:(x0+x1)/2, labelY:midY
    });

    const c=src.color;
    const ra=parseInt(c.slice(1,3),16),ga=parseInt(c.slice(3,5),16),ba=parseInt(c.slice(5,7),16);
    const isHov=hoveredFlow&&hoveredFlow.flow.from===f.from&&hoveredFlow.flow.to===f.to;
    const grad=ctx.createLinearGradient(x0,0,x1,0);
    grad.addColorStop(0,`rgba(${ra},${ga},${ba},${isHov?0.85:0.45})`);
    grad.addColorStop(1,`rgba(${ra},${ga},${ba},${isHov?0.55:0.1})`);
    ctx.fillStyle=grad; ctx.fill(path);
  });

  // Draw nodes + labels (on top of flows)
  Object.entries(nmap).forEach(([id,nd])=>{
    ctx.fillStyle=nd.color; ctx.fillRect(nd.x,nd.y,nodeW,nd.h);
    const isLeft=nd.ci===0, isRight=nd.ci===sankeyData.cols.length-1;
    ctx.fillStyle='#e8e8f0'; ctx.font=`bold ${9.5*dpr}px DM Sans,sans-serif`;
    if(isLeft){ctx.textAlign='right';ctx.fillText(nd.node.label,nd.x-8*dpr,nd.y+nd.h/2+4*dpr);}
    else if(isRight){ctx.textAlign='left';ctx.fillText(nd.node.label,nd.x+nodeW+8*dpr,nd.y+nd.h/2+4*dpr);}
    else{ctx.textAlign='center';ctx.fillText(nd.node.label,nd.x+nodeW/2,nd.y-9*dpr);}
    if(nd.h>18*dpr){
      ctx.fillStyle='rgba(255,255,255,0.9)';ctx.font=`${9*dpr}px DM Mono,monospace`;ctx.textAlign='center';
      ctx.fillText(nd.node.value,nd.x+nodeW/2,nd.y+nd.h/2+3.5*dpr);
    }
  });

  // Draw hovered flow label inline (like the screenshot)
  if(hoveredFlow){
    const {flow,src,dst,labelX,labelY,fh}=hoveredFlow;
    const label=`${flow.v}`;
    const pad2=7*dpr, h2=18*dpr;
    ctx.font=`bold ${11*dpr}px DM Mono,monospace`;
    const tw=ctx.measureText(label).width;
    // pill background
    ctx.fillStyle='rgba(15,15,20,0.82)';
    ctx.beginPath();
    ctx.roundRect(labelX-tw/2-pad2, labelY-h2/2, tw+pad2*2, h2, 4*dpr);
    ctx.fill();
    // text
    ctx.fillStyle='#ffffff';
    ctx.textAlign='center';
    ctx.fillText(label,labelX,labelY+4*dpr);
  }
}

// Sankey hover — hit-test flows with Path2D.isPointInPath
sk.addEventListener('mousemove',e=>{
  const rect=sk.getBoundingClientRect(),dpr=sankeyDpr;
  const mx=(e.clientX-rect.left)*dpr,my=(e.clientY-rect.top)*dpr;
  const ctx=kCtx;

  // Check node hover first
  let nodeHit=null;
  Object.entries(sankeyNmap).forEach(([id,nd])=>{
    if(mx>=nd.x&&mx<=nd.x+sankeyNodeW&&my>=nd.y&&my<=nd.y+nd.h) nodeHit=nd;
  });

  // Check flow hover
  let flowHit=null;
  if(!nodeHit){
    for(let i=sankeyFlowCache.length-1;i>=0;i--){
      const fc=sankeyFlowCache[i];
      if(ctx.isPointInPath(fc.path,mx,my)){flowHit=fc;break;}
    }
  }

  const prevHov=hoveredFlow;
  hoveredFlow=flowHit||null;
  if(prevHov!==flowHit) drawSankey();

  if(nodeHit){
    const pct=(nodeHit.node.value/1000*100).toFixed(1);
    showTip(
      `<b>${nodeHit.node.label}</b><br><span style="color:var(--text-dim)">${nodeHit.colLabel}</span><br>` +
      `<span style="color:var(--accent);font-size:13px">${nodeHit.node.value}</span> tracks · ${pct}%`,
      e.clientX, e.clientY
    );
  } else if(flowHit){
    const {flow,src,dst}=flowHit;
    const fromLabel=flow.fromLabel||src.node.label;
    const toLabel=flow.toLabel||dst.node.label;
    const pct=(flow.v/1000*100).toFixed(1);
    showTip(
      `<b>${fromLabel}</b> → <b>${toLabel}</b><br>` +
      `<span style="color:var(--accent);font-size:13px">${flow.v}</span> tracks · ${pct}%`,
      e.clientX, e.clientY
    );
  } else hideTip();
});
sk.addEventListener('mouseleave',()=>{
  hoveredFlow=null;
  hideTip();
  drawSankey();
});
sk.addEventListener('click', e => {
  const rect = sk.getBoundingClientRect(), dpr = sankeyDpr;
  const mx = (e.clientX - rect.left)*dpr, my = (e.clientY - rect.top)*dpr;
  const ctx = kCtx;
  for (let i = sankeyFlowCache.length-1; i >= 0; i--) {
    const fc = sankeyFlowCache[i];
    if (ctx.isPointInPath(fc.path, mx, my)) {
      openSankeyModal(fc.flow);
      break;
    }
  }
});

// ── SLOPE ─────────────────────────────────────────────────────────────────────
const sl=document.getElementById('slopeCanvas');
const slCtx=sl.getContext('2d');
const dims=['loudness','valence','energy','speechiness','danceability'];
const dimLabels=['Loudness','Valence','Energy','Speechiness','Danceability'];
let hoveredLine=null;

function drawSlope(){
  resizeCanvas(sl);
  const W=sl.width,H=sl.height,dpr=devicePixelRatio;
  const pad={left:90*dpr,right:100*dpr,top:40*dpr,bottom:36*dpr};
  const pw=W-pad.left-pad.right,ph=H-pad.top-pad.bottom;
  const ctx=slCtx;
  ctx.clearRect(0,0,W,H);
  const colX=dims.map((_,i)=>pad.left+(i/(dims.length-1))*pw);

  // Grid lines
  ctx.strokeStyle='rgba(42,42,53,0.9)';ctx.lineWidth=1;
  colX.forEach(x=>{ctx.beginPath();ctx.moveTo(x,pad.top);ctx.lineTo(x,pad.top+ph);ctx.stroke();});
  // Y ticks
  ctx.fillStyle='rgba(153,153,170,0.7)';ctx.font=`${9*dpr}px DM Mono,monospace`;ctx.textAlign='right';
  for(let t=0;t<=10;t+=2){
    const y=pad.top+ph-(t/10)*ph;
    ctx.fillText((t/10).toFixed(1),pad.left-8*dpr,y+3*dpr);
  }
  // Column labels
  ctx.fillStyle='rgba(200,200,215,0.9)';ctx.font=`bold ${9.5*dpr}px DM Sans,sans-serif`;ctx.textAlign='center';
  dimLabels.forEach((l,i)=>ctx.fillText(l.toUpperCase(),colX[i],pad.top-16*dpr));

  // Lines
  topTrackFeatures.forEach((track,ti)=>{
    const c=slopeColors[ti];
    const ra=parseInt(c.slice(1,3),16),ga=parseInt(c.slice(3,5),16),ba=parseInt(c.slice(5,7),16);
    const isHov=hoveredLine===ti;
    const inComp = compSelected.includes(ti);
    const compIdx = compSelected.indexOf(ti);
    // Grey out all other tracks when any comparison selection is active
    const anyComp = compSelected.length > 0;
    const alpha = hoveredLine!=null
      ? (isHov ? 1 : 0.08)
      : anyComp
        ? (inComp ? 1 : 0.07)
        : 0.6;
    ctx.beginPath();
    dims.forEach((d,i)=>{
      const x=colX[i],y=pad.top+ph-track[d]*ph;
      i===0?ctx.moveTo(x,y):ctx.lineTo(x,y);
    });
    const compC = compSelected.includes(ti) ? compColors[compSelected.indexOf(ti)] : null;
    const rc = compC ? parseInt(compC.slice(1,3),16) : ra;
    const gc = compC ? parseInt(compC.slice(3,5),16) : ga;
    const bc = compC ? parseInt(compC.slice(5,7),16) : ba;
    ctx.strokeStyle=`rgba(${rc},${gc},${bc},${alpha})`;
    ctx.lineWidth=(isHov||compSelected.includes(ti)?2.5:1.5)*dpr; ctx.stroke();
    // Dots — enlarge the hovered dimension's dot
    dims.forEach((d,i)=>{
      const x=colX[i],y=pad.top+ph-track[d]*ph;
      const isDimHov=isHov&&hoveredDim===i;
      ctx.beginPath();ctx.arc(x,y,(isDimHov?6:isHov?4:2.5)*dpr,0,Math.PI*2);
      ctx.fillStyle=`rgba(${ra},${ga},${ba},${alpha})`;ctx.fill();
      if(isDimHov){ctx.strokeStyle=`rgba(255,255,255,0.9)`;ctx.lineWidth=1.5*dpr;ctx.stroke();}
    });
    // End label
    const lx=colX[dims.length-1],ly=pad.top+ph-track[dims[dims.length-1]]*ph;
    ctx.fillStyle=`rgba(${ra},${ga},${ba},${hoveredLine===null||isHov?0.85:0.1})`;
    ctx.font=`${isHov?10:8.5}*${dpr}px DM Mono,monospace`;
    ctx.font=`${(isHov?10:8.5)*dpr}px DM Mono,monospace`;
    ctx.textAlign='left';
    ctx.fillText(track.name,lx+8*dpr,ly+3.5*dpr);
  });
}

let hoveredDim=null;

function setAfActive(dimIndex){
  document.querySelectorAll('.af-item').forEach(el=>el.classList.remove('active'));
  if(dimIndex!=null){
    const key=dims[dimIndex];
    const el=document.querySelector(`.af-item[data-dim="${key}"]`);
    if(el){
      el.classList.add('active');
      el.scrollIntoView({block:'nearest',behavior:'smooth'});
    }
  }
}

sl.addEventListener('mousemove',e=>{
  const rect=sl.getBoundingClientRect(),dpr=devicePixelRatio;
  const W=sl.width,H=sl.height;
  const pad={left:90*dpr,right:100*dpr,top:40*dpr,bottom:36*dpr};
  const pw=W-pad.left-pad.right,ph=H-pad.top-pad.bottom;
  const mx=(e.clientX-rect.left)*dpr,my=(e.clientY-rect.top)*dpr;
  const colX=dims.map((_,i)=>pad.left+(i/(dims.length-1))*pw);
  let foundLine=null,foundDim=null,minD=Infinity;
  topTrackFeatures.forEach((track,ti)=>{
    dims.forEach((d,i)=>{
      const x=colX[i],y=pad.top+ph-track[d]*ph;
      const dist=Math.sqrt((mx-x)**2+(my-y)**2);
      if(dist<16*dpr&&dist<minD){minD=dist;foundLine=ti;foundDim=i;}
    });
  });
  hoveredLine=foundLine;
  hoveredDim=foundDim;
  setAfActive(foundDim);
  if(foundLine!=null&&foundDim!=null){
    const t=topTrackFeatures[foundLine];
    const dimKey=dims[foundDim];
    const dimLabel=dimLabels[foundDim];
    const val=t[dimKey].toFixed(3);
    showTip(
      `<b>${t.name}</b><br><span style="color:var(--text-dim)">${t.artist}</span><br>` +
      `<span style="color:var(--accent)">${dimLabel}</span>: <b>${val}</b>`,
      e.clientX, e.clientY
    );
  } else hideTip();
  drawSlope();
});
sl.addEventListener('mouseleave',()=>{hoveredLine=null;hoveredDim=null;setAfActive(null);hideTip();drawSlope();});
sl.addEventListener('click', e => {
  const rect = sl.getBoundingClientRect(), dpr = devicePixelRatio;
  const W = sl.width, H = sl.height;
  const pad = {left:90*dpr, right:100*dpr, top:40*dpr, bottom:36*dpr};
  const pw = W-pad.left-pad.right, ph = H-pad.top-pad.bottom;
  const mx = (e.clientX-rect.left)*dpr, my = (e.clientY-rect.top)*dpr;
  const colX = dims.map((_,i) => pad.left+(i/(dims.length-1))*pw);
  let found = null, minD = Infinity;
  topTrackFeatures.forEach((track, ti) => {
    dims.forEach((d, i) => {
      const x = colX[i], y = pad.top+ph-track[d]*ph;
      const dist = Math.sqrt((mx-x)**2+(my-y)**2);
      if (dist < 20*dpr && dist < minD) { minD = dist; found = ti; }
    });
  });
  if (found !== null) toggleComparison(found);
});

