const topArtists = ["Bring Me The Horizon","Bullet For My Valentine","Lamb of God","I Prevail","Architects","The Devil Wears Prada","Ice Nine Kills","A Day To Remember","Dead by April","Bad Omens","Our Last Night","Motionless In White","Wage War","The Acacia Strain","Asking Alexandria","Falling In Reverse","We Came As Romans","Parkway Drive","The Amity Affliction","Upon A Burning Body","Spiritbox","Periphery","Every Time I Die","The Plot In You","Killswitch Engage","Electric Callboy","Trivium","King 810","Escape the Fate","All That Remains"];
let selectedArtists = new Set();

function buildArtistFilter() {
  const wrap = document.getElementById('artistFilterWrap');
  wrap.innerHTML = '';

  // Clear all pill
  const clearBtn = document.createElement('button');
  clearBtn.className = 'artist-pill clear-all';
  clearBtn.textContent = 'Clear all';
  clearBtn.addEventListener('click', () => { selectedArtists.clear(); buildArtistFilter(); drawScatter(); });
  wrap.appendChild(clearBtn);

  topArtists.forEach(artist => {
    const pill = document.createElement('button');
    pill.className = 'artist-pill' + (selectedArtists.has(artist) ? ' selected' : '');
    pill.textContent = artist;
    pill.addEventListener('click', () => {
      if (selectedArtists.has(artist)) selectedArtists.delete(artist);
      else selectedArtists.add(artist);
      buildArtistFilter();
      drawScatter();
    });
    wrap.appendChild(pill);
  });
  updateTrackCount();
}

function updateTrackCount() {
  const visible = scatterData.filter(d => {
    const tp = scatterFilter === 'all' || d.t === scatterFilter;
    const lp = lyricFilter === 'all' || (lyricFilter === 'explicit' ? d.x : !d.x);
    const ap = selectedArtists.size === 0 || selectedArtists.has(d.a);
    return tp && lp && ap;
  }).length;
  const el = document.getElementById('trackCountVal');
  if (el) el.textContent = visible;
}

