function openSankeyModal(flow) {
  const key = flow.from + '→' + flow.to;
  const tracks = sankeyTrackLookup[key] || [];

  const fromLabel = flow.fromLabel || flow.from;
  const toLabel   = flow.toLabel   || flow.to;

  document.getElementById('modalTitle').textContent = `${fromLabel} → ${toLabel}`;
  document.getElementById('modalSubtitle').textContent = `${flow.v} tracks in this connection`;

  const list = document.getElementById('modalTrackList');
  list.innerHTML = '';
  tracks.forEach((t, i) => {
    const li = document.createElement('li');
    li.className = 'modal-track-item';
    li.innerHTML = `<span class="modal-track-num">${i+1}</span>
      <span class="modal-track-name">${t.track_name}</span>
      <span class="modal-track-artist">${t.artists}</span>`;
    list.appendChild(li);
  });

  document.getElementById('sankeyModal').classList.add('open');
}

document.getElementById('modalClose').addEventListener('click', () => {
  document.getElementById('sankeyModal').classList.remove('open');
});
document.getElementById('sankeyModal').addEventListener('click', e => {
  if (e.target === document.getElementById('sankeyModal'))
    document.getElementById('sankeyModal').classList.remove('open');
});

// ── SLOPE COMPARISON ─────────────────────────────────────────────────────────
const compColors = ['#e8345a','#f5c842','#4ade80'];
let compSelected = []; // max 3 track indices

function toggleComparison(trackIndex) {
  const idx = compSelected.indexOf(trackIndex);
  if (idx >= 0) {
    compSelected.splice(idx, 1);
  } else {
    if (compSelected.length >= 3) return; // max 3
    compSelected.push(trackIndex);
  }
  renderCompPanel();
  drawSlope();
}

function renderCompPanel() {
  const slots = document.getElementById('compSlots');
  const bars  = document.getElementById('compBars');
  slots.innerHTML = '';
  bars.innerHTML  = '';

  for (let i = 0; i < 3; i++) {
    const slot = document.createElement('div');
    if (i < compSelected.length) {
      const ti = compSelected[i];
      const t  = topTrackFeatures[ti];
      const c  = compColors[i];
      slot.className = 'comp-slot';
      slot.style.borderColor = c + '66';
      slot.innerHTML = `
        <div class="comp-slot-info">
          <div class="comp-slot-name">${t.name}</div>
          <div class="comp-slot-artist">${t.artist}</div>
        </div>
        <button class="comp-slot-remove" data-i="${i}">✕</button>`;
    } else {
      slot.className = 'comp-slot empty';
      slot.textContent = `Slot ${i+1} — click a track`;
    }
    slots.appendChild(slot);
  }

  slots.querySelectorAll('.comp-slot-remove').forEach(btn => {
    btn.addEventListener('click', () => {
      compSelected.splice(parseInt(btn.dataset.i), 1);
      renderCompPanel(); drawSlope();
    });
  });

  if (compSelected.length > 0) {
    // Show all 5 audio features for each selected track
    const featureKeys   = ['loudness','valence','energy','speechiness','danceability'];
    const featureLabels = ['Loudness','Valence','Energy','Speechiness','Danceability'];

    featureKeys.forEach((key, fi) => {
      // Section header
      const header = document.createElement('div');
      header.style.cssText = 'font-family:"DM Mono",monospace;font-size:9px;letter-spacing:0.15em;text-transform:uppercase;color:var(--text-dim);margin:12px 0 6px;padding-top:8px;border-top:1px solid var(--border)';
      if (fi === 0) header.style.borderTop = 'none';
      header.textContent = featureLabels[fi];
      bars.appendChild(header);

      const maxVal = Math.max(...compSelected.map(ti => topTrackFeatures[ti][key]));

      compSelected.forEach((ti, ci) => {
        const t = topTrackFeatures[ti];
        const c = compColors[ci];
        const pct = maxVal > 0 ? (t[key] / maxVal * 100).toFixed(1) : 0;
        const row = document.createElement('div');
        row.className = 'comp-bar-row';
        row.innerHTML = `
          <div class="comp-bar-label" style="color:${c}">${t.name}</div>
          <div class="comp-bar-track"><div class="comp-bar-fill" style="width:0%;background:${c}" data-w="${pct}%"></div></div>
          <div class="comp-bar-val">${t[key].toFixed(3)}</div>`;
        bars.appendChild(row);
      });
    });

    setTimeout(() => {
      document.querySelectorAll('.comp-bar-fill').forEach(el => el.style.width = el.dataset.w);
    }, 50);
  } else {
    bars.innerHTML = '<div class="comp-hint">Click any track line on the chart to add it to comparison.</div>';
  }
}

// ── INIT ──────────────────────────────────────────────────────────────────────
drawScatter();
buildTop10();
buildArtistFilter();
renderCompPanel();
window.addEventListener('resize',()=>{
  const id=document.querySelector('.panel.active').id.replace('panel-','');
  if(id==='scatter')drawScatter();
  if(id==='sankey')drawSankey();
  if(id==='slope')drawSlope();
});